import{_ as l,C as t,o as i,c as d,a2 as a,b as c,w as n,a as u,E as s,a3 as p}from"./chunks/framework.CHjbm2Wd.js";const A=JSON.parse('{"title":"GNC software architecture & interfaces","description":"Rate groups, data contracts, mode logic, and the integration seams where projects fail.","frontmatter":{"title":"GNC software architecture & interfaces","description":"Rate groups, data contracts, mode logic, and the integration seams where projects fail."},"headers":[],"relativePath":"gnc/architecture.md","filePath":"gnc/architecture.md","lastUpdated":1792993690000}'),h={name:"gnc/architecture.md"};function m(g,e,b,f,v,y){const r=t("Mermaid"),o=t("Quiz");return i(),d("div",null,[e[1]||(e[1]=a('<h1 id="gnc-software-architecture-interfaces" tabindex="-1">GNC software architecture &amp; interfaces <a class="header-anchor" href="#gnc-software-architecture-interfaces" aria-label="Permalink to &quot;GNC software architecture &amp; interfaces&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Why this matters</p><p>Most GNC failures in integration are not exotic math. They are stale data, a wrong frame, a missing validity flag, a mode transition that raced, or a rate group that missed its deadline. Architecture is how you make those failures visible and testable before flight.</p></div><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><ul><li>Draw the GNC data flow from sensors to actuators.</li><li>Choose rate groups and justify them with timing budgets.</li><li>Define message contracts with units, frames, timestamps, and validity.</li><li>Design mode logic and fault transitions.</li><li>Separate guidance, navigation, control, and FDIR responsibilities.</li><li>Identify the integration bugs that appear in SIL/HIL.</li></ul><h2 id="the-module-map" tabindex="-1">The module map <a class="header-anchor" href="#the-module-map" aria-label="Permalink to &quot;The module map&quot;">​</a></h2>',5)),(i(),c(p,null,{default:n(()=>[s(r,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20S%5BSensors%3Cbr%2F%3EIMU%2C%20star%20tracker%2C%20altimeter%2C%20camera%5D%20--%3E%20N%5BNavigation%3Cbr%2F%3Estate%20estimate%20%2B%20covariance%5D%0A%20%20%20%20N%20--%3E%20G%5BGuidance%3Cbr%2F%3Etrajectory%20%2B%20command%5D%0A%20%20%20%20G%20--%3E%20C%5BControl%3Cbr%2F%3Eattitude%2Fthrottle%5D%0A%20%20%20%20C%20--%3E%20A%5BActuators%3Cbr%2F%3Eengine%2C%20gimbal%2C%20RCS%5D%0A%20%20%20%20A%20--%3E%20P%5BPlant%20%2F%20vehicle%5D%0A%20%20%20%20P%20--%3E%20S%0A%20%20%20%20N%20--%3E%20F%5BFDIR%20%2F%20mode%20manager%5D%0A%20%20%20%20G%20--%3E%20F%0A%20%20%20%20C%20--%3E%20F%0A%20%20%20%20F%20--%3E%20G%0A%20%20%20%20F%20--%3E%20C%0A%20%20%20%20N%20--%3E%20T%5BTelemetry%5D%0A%20%20%20%20G%20--%3E%20T%0A%20%20%20%20C%20--%3E%20T%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[u(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<p>The arrows are messages, not function calls. In a flight architecture, each module should be testable in isolation with recorded inputs.</p><h2 id="rate-groups" tabindex="-1">Rate groups <a class="header-anchor" href="#rate-groups" aria-label="Permalink to &quot;Rate groups&quot;">​</a></h2><p>A rate group is a set of functions that run at the same frequency. Typical descent rates:</p><table tabindex="0"><thead><tr><th>Function</th><th>Typical rate</th><th>Why</th></tr></thead><tbody><tr><td>IMU sampling</td><td>100–400 Hz</td><td>Capture body dynamics and vibration</td></tr><tr><td>Attitude control</td><td>50–100 Hz</td><td>Fast enough for rigid-body modes and actuator limits</td></tr><tr><td>Navigation update</td><td>10–50 Hz</td><td>Sensor fusion and propagation</td></tr><tr><td>Guidance</td><td>1–10 Hz</td><td>Trajectory is slower than attitude</td></tr><tr><td>Mode/FDIR</td><td>1–10 Hz</td><td>Fault detection latency vs processor load</td></tr><tr><td>Telemetry</td><td>1–10 Hz</td><td>Downlink bandwidth</td></tr></tbody></table><p>These are starting points, not requirements. The correct rate comes from the closed-loop bandwidth, the sensor dynamics, the actuator dynamics, and the CPU budget. A 10 Hz controller cannot stabilize a mode at 5 Hz.</p><h3 id="timing-budget" tabindex="-1">Timing budget <a class="header-anchor" href="#timing-budget" aria-label="Permalink to &quot;Timing budget&quot;">​</a></h3><p>For each rate group, account for:</p><ul><li>sensor read and timestamping,</li><li>navigation propagation,</li><li>guidance computation,</li><li>control computation,</li><li>actuator command write,</li><li>telemetry/logging,</li><li>margin.</li></ul><p>If the worst-case execution time plus jitter exceeds the period, the loop is not schedulable. Measure it; do not assume it.</p><h2 id="data-contracts" tabindex="-1">Data contracts <a class="header-anchor" href="#data-contracts" aria-label="Permalink to &quot;Data contracts&quot;">​</a></h2><p>A message is an interface. Define it like one:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NavState</span></span>
<span class="line"><span>  timestamp_met_s        double, monotonic</span></span>
<span class="line"><span>  timestamp_utc          double, for logs</span></span>
<span class="line"><span>  frame_position         enum (MCI, MCMF, ENU)</span></span>
<span class="line"><span>  frame_velocity         enum</span></span>
<span class="line"><span>  position_m[3]          double</span></span>
<span class="line"><span>  velocity_mps[3]        double</span></span>
<span class="line"><span>  attitude               quaternion, q_body_from_frame, scalar-first</span></span>
<span class="line"><span>  attitude_valid         bool</span></span>
<span class="line"><span>  covariance_diag[15]    double, optional</span></span>
<span class="line"><span>  sequence               uint32</span></span>
<span class="line"><span>  checksum               uint16</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>Rules:</p><ul><li><strong>Units in the name or the schema.</strong> <code>altitude_m</code>, not <code>altitude</code>.</li><li><strong>Frame in the name or the schema.</strong> <code>vel_enu_mps</code>.</li><li><strong>Timestamp and time scale.</strong> Monotonic MET for scheduling; UTC for operations.</li><li><strong>Validity and quality.</strong> A star tracker quaternion without a validity flag is a trap.</li><li><strong>Sequence and checksum.</strong> Detect drops and corruption.</li><li><strong>Fixed layout and endianness.</strong> If it goes on a wire, serialize explicitly.</li><li><strong>Version.</strong> Interfaces change; record the version.</li></ul><h2 id="modes-and-transitions" tabindex="-1">Modes and transitions <a class="header-anchor" href="#modes-and-transitions" aria-label="Permalink to &quot;Modes and transitions&quot;">​</a></h2><p>A mode manager is a state machine with guards, actions, and priorities. A descent mode set might be:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SAFE → STANDBY → ATTITUDE_HOLD → DESCENT_BRAKING → DESCENT_APPROACH</span></span>
<span class="line"><span>     → TERMINAL_DESCENT → TOUCHDOWN → SAFED</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Plus fault modes:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ANY → SAFE</span></span>
<span class="line"><span>ANY → ABORT (if available)</span></span>
<span class="line"><span>TERMINAL_DESCENT → DIVERT (if hazard detected)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Each transition needs:</p><ul><li>a <strong>guard</strong> (conditions, sensor validity, time, authority),</li><li>an <strong>action</strong> (command, configuration, telemetry),</li><li>a <strong>priority</strong> (fault transitions override nominal),</li><li>a <strong>test</strong> (nominal and off-nominal).</li></ul><p>Avoid ambiguous states. “Descent” and “safe” at the same time is a design bug. Use a single authoritative mode variable and make transitions atomic.</p><h2 id="fdir-responsibilities" tabindex="-1">FDIR responsibilities <a class="header-anchor" href="#fdir-responsibilities" aria-label="Permalink to &quot;FDIR responsibilities&quot;">​</a></h2><p>Fault detection, isolation, and recovery should be a separate concern from guidance and control:</p><ul><li><strong>Detection:</strong> thresholds, rate limits, stale data, watchdogs, checksums, voting, model residuals.</li><li><strong>Isolation:</strong> identify the failed unit or signal; avoid disabling a healthy redundant unit.</li><li><strong>Recovery:</strong> retry, reset, switch redundant unit, enter safe mode, abort.</li><li><strong>Reporting:</strong> event, telemetry, timestamp, and enough context to reconstruct the decision.</li></ul><p>A controller should not silently ignore a failed sensor. A mode manager should not depend on a single unvalidated measurement.</p><h2 id="architecture-patterns" tabindex="-1">Architecture patterns <a class="header-anchor" href="#architecture-patterns" aria-label="Permalink to &quot;Architecture patterns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pattern</th><th>Strength</th><th>Risk</th></tr></thead><tbody><tr><td><strong>Cyclic executive</strong></td><td>Simple, deterministic, easy to analyze</td><td>Poor for asynchronous events, priority inversion avoided by design</td></tr><tr><td><strong>RTOS tasks + queues</strong></td><td>Responsive, modular</td><td>Priority inversion, jitter, more complex timing analysis</td></tr><tr><td><strong>Publish/subscribe</strong></td><td>Loose coupling, testable</td><td>Message drops, ordering, backpressure</td></tr><tr><td><strong>Layered</strong></td><td>Clear responsibilities</td><td>Layer leakage, duplicated state</td></tr><tr><td><strong>Data-centric</strong></td><td>One authoritative state</td><td>Hidden coupling, stale data</td></tr><tr><td><strong>Active/passive redundancy</strong></td><td>Fault tolerance</td><td>Switchover transients, synchronization</td></tr></tbody></table><p>cFS uses a publish/subscribe software bus with a cyclic scheduler and apps. An RTOS design might use rate-monotonic tasks with queues. Both can work; the evidence requirements differ.</p><h2 id="integration-bugs-you-will-actually-see" tabindex="-1">Integration bugs you will actually see <a class="header-anchor" href="#integration-bugs-you-will-actually-see" aria-label="Permalink to &quot;Integration bugs you will actually see&quot;">​</a></h2><ol><li><strong>Frame mismatch at a module boundary.</strong> Navigation outputs MCMF, guidance expects ENU.</li><li><strong>Unit mismatch.</strong> Altitude in km, velocity in m/s, guidance in meters.</li><li><strong>Stale data.</strong> Guidance uses a nav state from 500 ms ago during a fast descent.</li><li><strong>Missing validity.</strong> A star tracker is in “lost in space” but the quaternion is still propagated.</li><li><strong>Timestamp mismatch.</strong> Sensor time is UTC, control time is MET, and the offset is wrong.</li><li><strong>Mode race.</strong> Two transitions fire in the same cycle; the last writer wins.</li><li><strong>Initialization order.</strong> Control runs before navigation has a valid state.</li><li><strong>Double buffering.</strong> The consumer reads the buffer while the producer writes it.</li><li><strong>Queue overflow.</strong> A high-rate sensor overruns a low-rate consumer.</li><li><strong>Endianness.</strong> The packet looks right in a hex dump but the float is byte-swapped.</li></ol><p>Each of these is a test case. Write them down.</p><h2 id="a-minimal-interface-review-checklist" tabindex="-1">A minimal interface review checklist <a class="header-anchor" href="#a-minimal-interface-review-checklist" aria-label="Permalink to &quot;A minimal interface review checklist&quot;">​</a></h2><ul><li>[ ] Every message has a timestamp and a time scale.</li><li>[ ] Every vector has a frame and a unit.</li><li>[ ] Every measurement has a validity/quality flag.</li><li>[ ] Every command has a range check and an acknowledgment.</li><li>[ ] Every mode transition has a guard and a test.</li><li>[ ] Every rate group has a measured worst-case execution time.</li><li>[ ] Every fault has a detection latency, isolation action, and recovery.</li><li>[ ] Every interface change has a version and a compatibility note.</li></ul><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><ol><li>Draw the data flow for your 6DOF sim. Label each message with rate, frame, units, and timestamp source.</li><li>Write the interface table for <code>NavState</code>, <code>GuidanceCmd</code>, and <code>ActuatorCmd</code>.</li><li>Implement a mode manager with <code>SAFE</code>, <code>ATTITUDE_HOLD</code>, <code>DESCENT</code>, and <code>TOUCHDOWN</code>. Add a stale-nav fault that forces <code>SAFE</code>.</li><li>Inject a 500 ms nav delay. Does guidance still meet the landing requirement? What changes?</li><li>Add a queue between a 100 Hz IMU and a 10 Hz guidance module. What is the maximum age of the data? What happens when it overflows?</li></ol>`,36)),s(o,{question:"Guidance receives a nav state with a valid quaternion but `attitude_valid = false`. What is the correct architectural response?",options:"Use the quaternion anyway; it is numerically valid|Treat the state as invalid, use the last valid state within a bounded age, or enter a defined fault mode|Average it with the previous quaternion|Increase the guidance rate",answer:"1",explanation:"Validity is part of the contract. A numerically well-formed quaternion can still be meaningless. The architecture needs a bounded fallback and an explicit fault response."}),e[3]||(e[3]=a('<h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><ul><li><a href="https://nasa.github.io/cFS/" target="_blank" rel="noreferrer">NASA cFS documentation</a> — a concrete publish/subscribe flight architecture.</li><li><a href="https://www.nasa.gov/connect/ebooks/nasa-systems-engineering-handbook/" target="_blank" rel="noreferrer">NASA Systems Engineering Handbook</a> — interfaces, requirements, and verification.</li><li><a href="https://nodis3.gsfc.nasa.gov/displayDir.cfm?t=NPR&amp;c=7150&amp;s=2" target="_blank" rel="noreferrer">NPR 7150.2</a> — software lifecycle and assurance requirements.</li><li><a href="https://ccsds.org/" target="_blank" rel="noreferrer">CCSDS Space Packet Protocol</a> — the wire format behind many space interfaces.</li></ul><p>Next: <a href="./../test/verification.html">V&amp;V for flight software</a>.</p>',3))])}const _=l(h,[["render",m]]);export{A as __pageData,_ as default};
